('JSS1', null, 'Digital Technologies', 'Digital safety', 'Which is the safest password practice?', 'Use your first name only.', 'Share your password with classmates.', 'Use a strong password and keep it private.', 'Write the password on a public noticeboard.', 'C', 'A strong private password helps protect an account from unauthorised access.', 'easy', 1),
('JSS1', null, 'Digital Technologies', 'Online safety', 'A stranger online asks for your one-time password. What should you do?', 'Send it immediately.', 'Post it in a group chat.', 'Keep it private and tell a trusted adult.', 'Use it as your username.', 'C', 'One-time passwords are private security codes and should never be shared.', 'easy', 1),
